 */
export async function runSingleAllowlistedCommand(
  command: string,
  projectRoot: string,
  options: SingleCommandExecutionOptions = {},
): Promise<SingleCommandExecutionResult> {
  const { executable, args } = parseAllowlistedCommand(command);
  const { cwd, timeoutMs, ...runOptions } = options;
  const configuredTimeoutMs = timeoutMs ?? resolveEvidenceCommandTimeoutMs(
    { executable, args },
    loadConfig(projectRoot).validate?.evidenceCommandTimeoutOverrides,
  );
  const validationCommand: ValidationCommand = {
    label: 'verification-evidence-command',
    command: executable,
    args,
    ...(cwd ? { cwd } : {}),
    timeoutMs: configuredTimeoutMs,
  };
  const result = await runValidationCommand(
    validationCommand,
    projectRoot,
    DEFAULT_VALIDATE_COMMAND_TIMEOUT_MS,
    runOptions,
  );
  if (runOptions.abortSignal?.aborted) {
    throw runOptions.abortSignal.reason instanceof Error
      ? runOptions.abortSignal.reason
      : new Error('verification evidence command aborted');
  }
  if (
    result.timedOut
    && typeof runOptions.deadlineAt === 'number'
    && Date.now() >= runOptions.deadlineAt
  ) {
    throw runOptions.deadlineError?.()
      ?? new Error(`verification evidence command deadline exceeded at ${runOptions.deadlineAt}`);
  }
  return {
    executable,
    args,
    code: result.code,
    output: result.output,
    timedOut: Boolean(result.timedOut),
    durationMs: result.durationMs,
  };
